// AAD: các giá trị không đổi xác định vị trí của bản mã
static byte[] aad(String tenantId, long customerId) {
    return ("v1|" + tenantId + "|customers.national_id|" + customerId).getBytes(StandardCharsets.UTF_8);
}

byte[] encrypt(SecretKey dataKey, String plain, byte[] aad) throws GeneralSecurityException {
    byte[] nonce = new byte[12];
    RANDOM.nextBytes(nonce);
    Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
    cipher.init(Cipher.ENCRYPT_MODE, dataKey, new GCMParameterSpec(128, nonce));
    cipher.updateAAD(aad);                     // không mã hoá, nhưng nằm trong tag
    byte[] ct = cipher.doFinal(plain.getBytes(StandardCharsets.UTF_8));
    return ByteBuffer.allocate(12 + ct.length).put(nonce).put(ct).array();
}

String decrypt(SecretKey dataKey, byte[] blob, byte[] aad) throws GeneralSecurityException {
    Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
    cipher.init(Cipher.DECRYPT_MODE, dataKey, new GCMParameterSpec(128, blob, 0, 12));
    cipher.updateAAD(aad);
    return new String(cipher.doFinal(blob, 12, blob.length - 12), StandardCharsets.UTF_8);
}

